import React from 'react';
import { useState, useEffect } from 'react';
import { Bar } from 'react-chartjs-2';

function Dashboard() {
  // placeholder stats
  const [stats, setStats] = useState({scans:0,malware:0,reports:0});

  useEffect(() => {
    // fetch stats from backend when built
  }, []);

  const chartData = {
    labels: ['Safe','Suspicious','Malicious'],
    datasets: [{
      data: [10, 5, 2],
      backgroundColor: ['#28a745','#ffc107','#dc3545']
    }]
  };

  return (
    <div>
      <h2>Dashboard</h2>
      <p>Total scans: {stats.scans}</p>
      <p>Malware detected: {stats.malware}</p>
      <p>Vulnerability reports: {stats.reports}</p>
      <div className="card">
        <div className="card-body">
          <h5 className="card-title">Risk Distribution</h5>
          <Bar data={chartData} />
        </div>
      </div>
    </div>
  );
}

export default Dashboard;
